// ENG-2266: keyboard control + light dismiss for the advanced node search popovers.
const MODAL = ".dg-node-search-modal";
const INPUT = `${MODAL} [role="textbox"]`;
const TRIGGER = {
  filter: `${MODAL} button[aria-label^="Filter by type"]`,
  sort: `${MODAL} button[aria-label^="Sort by"]`,
  display: `${MODAL} button[aria-label="Display options"]`,
};
const PANEL = (trigger) => `${trigger} + div`;

const KEYS = {
  ArrowDown: { key: "ArrowDown", code: "ArrowDown", windowsVirtualKeyCode: 40, nativeVirtualKeyCode: 40 },
  ArrowUp: { key: "ArrowUp", code: "ArrowUp", windowsVirtualKeyCode: 38, nativeVirtualKeyCode: 38 },
  Tab: { key: "Tab", code: "Tab", windowsVirtualKeyCode: 9, nativeVirtualKeyCode: 9 },
  Enter: { key: "Enter", code: "Enter", windowsVirtualKeyCode: 13, nativeVirtualKeyCode: 13, text: "\r" },
};
const press = (client, name, times = 1, modifiers = 0) =>
  (async () => {
    for (let i = 0; i < times; i++) await client.key({ ...KEYS[name], modifiers });
  })();

const openSearch = async ({ client, json, vault }) => {
  await client.evaluate(`return app.commands.executeCommandById(${json(`${vault.pluginId}:open-node-search`)});`);
  await client.waitFor(`!!document.querySelector(${json(INPUT)})`, { label: "search input rendered" });
  await client.evaluate(`document.querySelector(${json(INPUT)}).focus(); return true;`);
};

const waitResults = ({ client, json }) =>
  client.waitFor(`document.querySelectorAll(${json(`${MODAL} [role="option"]`)}).length > 1`, {
    label: "results rendered",
    timeout: 15000,
  });

// Short description of the focused element, plus whether its ring is painted.
const focused = ({ client }) =>
  client.evaluate(`const el = document.activeElement;
    const s = getComputedStyle(el);
    return {
      label: (el.getAttribute("aria-label") || el.getAttribute("placeholder") || el.textContent || el.tagName).trim().slice(0, 30),
      tag: el.tagName, role: el.getAttribute("role"), type: el.getAttribute("type"),
      ring: s.boxShadow.includes("inset"), focusVisible: el.matches(":focus-visible"),
      inModal: !!el.closest(${JSON.stringify(MODAL)}),
    };`);

const isOpen = ({ client, json }, trigger) =>
  client.evaluate(`return document.querySelector(${json(trigger)})?.getAttribute("aria-expanded") === "true";`);

const activeResult = ({ client, json }) =>
  client.evaluate(`return Array.from(document.querySelectorAll(${json(`${MODAL} [role="option"]`)}))
    .findIndex((el) => el.getAttribute("aria-selected") === "true");`);

const click = async ({ client, json }, selector) => {
  const { x, y } = await client.evaluate(`const r = document.querySelector(${json(selector)}).getBoundingClientRect();
    return { x: r.left + r.width / 2, y: r.top + r.height / 2 };`);
  await client.send("Input.dispatchMouseEvent", { type: "mouseMoved", x, y });
  await client.send("Input.dispatchMouseEvent", { type: "mousePressed", x, y, button: "left", clickCount: 1 });
  await client.send("Input.dispatchMouseEvent", { type: "mouseReleased", x, y, button: "left", clickCount: 1 });
  await new Promise((r) => setTimeout(r, 150));
};

// Keyboard open: focus the trigger from the input with Tab-like intent, then Enter.
const keyboardOpen = async (ctx, trigger) => {
  const { client, json } = ctx;
  await client.evaluate(`document.querySelector(${json(trigger)}).focus(); return true;`);
  await press(client, "Enter");
  await client.waitFor(`!!document.querySelector(${json(PANEL(trigger))})`, { label: "panel open" });
  await new Promise((r) => setTimeout(r, 100));
};

const walk = async (ctx, name, times) => {
  const seq = [];
  for (let i = 0; i < times; i++) {
    await press(ctx.client, name);
    seq.push((await focused(ctx)).label);
  }
  return seq;
};

const sortKeyboardNav = {
  name: "Sort arrow keys wrap",
  input: "Enter on sort trigger; ArrowDown x7; ArrowUp x1; ArrowDown x1",
  expected: "focus starts on selected row with ring; 7 stops (5 rows + Asc/Desc) then wraps; Up from first goes to Desc; result highlight unchanged",
  run: async (ctx) => {
    await openSearch(ctx);
    await waitResults(ctx);
    const resultBefore = await activeResult(ctx);
    await keyboardOpen(ctx, TRIGGER.sort);
    const start = await focused(ctx);
    const down = await walk(ctx, "ArrowDown", 7);
    const up = await walk(ctx, "ArrowUp", 1);
    await press(ctx.client, "ArrowDown", 2); // land on a plain row for the screenshot
    const end = await focused(ctx);
    return { start, down, up, end, resultBefore, resultAfter: await activeResult(ctx), open: await isOpen(ctx, TRIGGER.sort) };
  },
  expect: (a) => ({
    pass:
      a.start.role === "menuitemradio" && a.start.ring && a.start.focusVisible &&
      new Set(a.down.slice(0, 7)).size === 7 && a.down[6] === a.start.label &&
      a.up[0] === a.down[5] && a.end.ring && a.resultBefore === a.resultAfter && a.open,
    actual: `start=${a.start.label} ring=${a.start.ring}; down=${a.down.join(" → ")}; up=${a.up[0]}; result ${a.resultBefore}→${a.resultAfter}`,
  }),
};

const tabCloses = (shift) => ({
  name: `Sort ${shift ? "Shift+Tab" : "Tab"} only closes`,
  input: `Enter on sort trigger; ArrowDown; ${shift ? "Shift+Tab" : "Tab"}`,
  expected: "panel closes; focus on sort trigger; sort unchanged",
  run: async (ctx) => {
    await openSearch(ctx);
    const label = () => ctx.client.evaluate(`return document.querySelector(${ctx.json(TRIGGER.sort)}).getAttribute("aria-label");`);
    await keyboardOpen(ctx, TRIGGER.sort);
    const before = await label();
    await press(ctx.client, "ArrowDown");
    await press(ctx.client, "Tab", 1, shift ? 8 : 0);
    await new Promise((r) => setTimeout(r, 100));
    return { open: await isOpen(ctx, TRIGGER.sort), focus: await focused(ctx), before, after: await label() };
  },
  expect: (a) => ({
    pass: !a.open && a.focus.label === a.before && a.before === a.after,
    actual: `open=${a.open}; focus=${a.focus.label}; sort ${a.before === a.after ? "unchanged" : "CHANGED"}`,
  }),
});

const mouseNoRing = {
  name: "Mouse open shows no ring",
  input: "click sort trigger",
  expected: "panel opens, focus on selected row, no focus ring",
  run: async (ctx) => {
    await openSearch(ctx);
    await click(ctx, TRIGGER.sort);
    return { open: await isOpen(ctx, TRIGGER.sort), focus: await focused(ctx) };
  },
  expect: (a) => ({
    pass: a.open && a.focus.role === "menuitemradio" && !a.focus.ring,
    actual: `open=${a.open}; focus=${a.focus.label}; ring=${a.focus.ring}`,
  }),
};

const switchPopover = {
  name: "Clicking another trigger switches",
  input: "click sort trigger; click filter trigger",
  expected: "sort closes and filter opens on one click",
  run: async (ctx) => {
    await openSearch(ctx);
    await click(ctx, TRIGGER.sort);
    const sortOpened = await isOpen(ctx, TRIGGER.sort);
    await click(ctx, TRIGGER.filter);
    return { sortOpened, sort: await isOpen(ctx, TRIGGER.sort), filter: await isOpen(ctx, TRIGGER.filter), focus: await focused(ctx) };
  },
  expect: (a) => ({
    pass: a.sortOpened && !a.sort && a.filter,
    actual: `sort=${a.sort}; filter=${a.filter}; focus=${a.focus.label}`,
  }),
};

const lightDismiss = {
  name: "Outside click closes and goes through",
  input: "open sort; click the 2nd result",
  expected: "sort closes; 2nd result highlighted (click went through)",
  run: async (ctx) => {
    await openSearch(ctx);
    await waitResults(ctx);
    await click(ctx, TRIGGER.sort);
    const before = await activeResult(ctx);
    await click(ctx, `${MODAL} [role="option"]:nth-child(2)`);
    return { open: await isOpen(ctx, TRIGGER.sort), before, after: await activeResult(ctx) };
  },
  expect: (a) => ({ pass: !a.open && a.after === 1, actual: `open=${a.open}; active result ${a.before}→${a.after}` }),
};

const escapeToInput = {
  name: "Escape closes and focuses search",
  input: "Enter on sort trigger; Escape",
  expected: "panel closes; modal stays; focus in search input",
  run: async (ctx) => {
    await openSearch(ctx);
    await keyboardOpen(ctx, TRIGGER.sort);
    await ctx.client.pressEscape();
    await new Promise((r) => setTimeout(r, 150));
    return {
      open: await isOpen(ctx, TRIGGER.sort),
      modal: await ctx.client.evaluate(`!!document.querySelector(${ctx.json(MODAL)})`),
      inInput: await ctx.client.evaluate(`document.activeElement === document.querySelector(${ctx.json(INPUT)})`),
    };
  },
  expect: (a) => ({ pass: !a.open && a.modal && a.inInput, actual: `open=${a.open}; modal=${a.modal}; focus in input=${a.inInput}` }),
};

const filterKeyboard = {
  name: "Type filter arrow keys wrap",
  input: "Enter on filter trigger; ArrowDown until back to start; ArrowUp x1",
  expected: "focus inside panel; arrows visit every item and wrap",
  run: async (ctx) => {
    await openSearch(ctx);
    await keyboardOpen(ctx, TRIGGER.filter);
    const count = await ctx.client.evaluate(`return document.querySelector(${ctx.json(PANEL(TRIGGER.filter))})
      .querySelectorAll('input:not([disabled]), button:not([disabled]), [tabindex]:not([tabindex="-1"])').length;`);
    const start = await focused(ctx);
    const down = await walk(ctx, "ArrowDown", count);
    const up = await walk(ctx, "ArrowUp", 1);
    await press(ctx.client, "ArrowDown", 2);
    return { count, start, down, up, open: await isOpen(ctx, TRIGGER.filter) };
  },
  expect: (a) => ({
    pass: a.count > 1 && a.down[a.count - 1] === a.start.label && a.up[0] === a.down[a.count - 2] && a.open,
    actual: `${a.count} items; start=${a.start.label} (${a.start.tag}); wrapped back=${a.down[a.count - 1] === a.start.label}`,
  }),
};

const filterLabelClick = {
  name: "Filter label/dot click toggles every time",
  input: "click first row's label text x2, then its colour dot x1",
  expected: "checkbox flips on each click; panel stays open",
  run: async (ctx) => {
    const { client, json } = ctx;
    await openSearch(ctx);
    await click(ctx, TRIGGER.filter);
    const row = `${PANEL(TRIGGER.filter)} label`;
    const checked = () => client.evaluate(`return document.querySelector(${json(`${row} input[type=checkbox]`)}).checked;`);
    const states = [await checked()];
    await click(ctx, `${row} span.truncate`);
    states.push(await checked());
    await click(ctx, `${row} span.truncate`);
    states.push(await checked());
    const hasDot = await client.evaluate(`!!document.querySelector(${json(`${row} span.rounded-full`)})`);
    if (hasDot) {
      await click(ctx, `${row} span.rounded-full`);
      states.push(await checked());
      await click(ctx, `${row} span.rounded-full`);
      states.push(await checked());
    }
    return { states, open: await isOpen(ctx, TRIGGER.filter) };
  },
  expect: (a) => ({
    pass: a.open && a.states.every((s, i) => i === 0 || s !== a.states[i - 1]),
    actual: `checked ${a.states.join(" → ")}; open=${a.open}`,
  }),
};

const displayKeyboard = {
  name: "Display options keyboard",
  input: "Enter on display trigger; ArrowDown; Enter",
  expected: "focus on toggle with ring; arrow wraps to itself; Enter toggles; stays open",
  run: async (ctx) => {
    const { client, json } = ctx;
    await openSearch(ctx);
    const state = () => client.evaluate(`return document.querySelector(${json(`${PANEL(TRIGGER.display)} [role=menuitemcheckbox]`)})?.getAttribute("aria-checked");`);
    await keyboardOpen(ctx, TRIGGER.display);
    const start = await focused(ctx);
    await press(client, "ArrowDown");
    const afterArrow = await focused(ctx);
    const before = await state();
    await press(client, "Enter");
    const after = await state();
    await press(client, "Enter"); // restore
    return { start, afterArrow, before, after, restored: await state(), open: await isOpen(ctx, TRIGGER.display) };
  },
  expect: (a) => ({
    pass: a.start.role === "menuitemcheckbox" && a.start.ring && a.afterArrow.role === "menuitemcheckbox" &&
      a.before !== a.after && a.restored === a.before && a.open,
    actual: `focus=${a.start.label} ring=${a.start.ring}; toggled ${a.before}→${a.after}; open=${a.open}`,
  }),
};

const darkRing = {
  name: "Sort ring in dark theme",
  input: "dark theme; Enter on sort trigger; ArrowDown x6 (to Asc)",
  expected: "inset ring visible on a direction button in dark theme",
  setup: async ({ client }) => ({ theme: await client.evaluate(`return app.vault.getConfig("theme");`) }),
  run: async (ctx) => {
    await ctx.client.evaluate(`app.changeTheme("obsidian"); return true;`);
    await openSearch(ctx);
    await keyboardOpen(ctx, TRIGGER.sort);
    await press(ctx.client, "ArrowDown", 5);
    return focused(ctx);
  },
  expect: (a) => ({ pass: a.ring && a.focusVisible, actual: `focus=${a.label} ring=${a.ring}` }),
  teardown: async ({ client, json }, { theme }) => {
    await client.evaluate(`app.changeTheme(${json(theme || "moonstone")}); return true;`);
  },
};

export default [
  sortKeyboardNav,
  tabCloses(false),
  tabCloses(true),
  mouseNoRing,
  switchPopover,
  lightDismiss,
  escapeToInput,
  filterKeyboard,
  filterLabelClick,
  displayKeyboard,
  darkRing,
];

